\title{The Probabilistic Backbone of Bayesian Play\\ in Social-Deduction Games}
\author{Aristotle}
\date{2026-07-10}

\begin{document}
\maketitle

\begin{abstract}
Social-deduction games such as \emph{Werewolf} and \emph{Mafia} pit an informed
malicious minority against an uninformed majority that must identify and eliminate
the minority through repeated group decisions under uncertainty. We isolate and
prove the exact probabilistic core of the widely used ``vote for the most
suspicious player'' heuristic. Our central result is a \emph{Symmetry Principle}:
when the only available evidence is the population census---$k$ werewolves hidden
among $n$ players---the posterior probability that any fixed player is a werewolf
equals the prior $k/n$ exactly. Consequently every player is equally suspicious, a
uniform vote is optimal, and the evidence-free per-round detection probability is
pinned at exactly $k/n$. We complement this with (i)~exact monotonicity of
suspicion in the number of werewolves and in the population size; (ii)~the
\emph{werewolf advantage} $A=k/(n-k)$ and a sharp \emph{parity threshold}, namely
that the werewolves are at least as numerous as the villagers if and only if
$n\le 2k$; (iii)~an \emph{exchangeability / survival law} stating that a fixed
player survives $t$ uniformly random removals with probability exactly $(n-t)/n$;
and (iv)~a well-founded recursive model of the full consensus-elimination game
whose villager win-probability is proved to lie in $[0,1]$. These results give a
rigorous, dimension-free foundation for optimal Bayesian play and recast the
informal $(1-k/(n-k))^2$ win-probability envelope as the exact parity criterion and
monotonicity statements that actually underlie it.
\end{abstract}

\section{Introduction}

A social-deduction game is a repeated elimination contest between two groups: an
\emph{informed minority} (the werewolves) who know each other's identities, and an
\emph{uninformed majority} (the villagers) who do not. In the canonical rules, a
population of $n$ players contains $k$ werewolves and $n-k$ villagers. Play
alternates between two kinds of rounds: at \emph{night} the werewolves collectively
remove one villager; on the \emph{day} all surviving players vote, and the plurality
target---possibly a werewolf, possibly a villager---is removed. The villagers win if
every werewolf is removed; the werewolves win the moment they reach \emph{parity},
becoming at least as numerous as the surviving villagers, since a coordinated bloc
then controls every subsequent vote.

The folklore villager strategy is Bayesian: maintain, for each player, a posterior
probability of being a werewolf and vote for the maximizer. The motivating claim of
this work is that this heuristic is optimal, that under census-only evidence the
posterior collapses to the prior $k/n$, and that the werewolves' structural
advantage is governed by the ratio $k/(n-k)$. Rather than fit an empirical curve to
simulated games, we extract the \emph{exact} identities behind the heuristic,
yielding dimension-free theorems that hold for all $n$ and $k$.

\section{Setup and Definitions}

Throughout, $n$ is the number of players and $k$ the number of werewolves,
$0\le k\le n$. All probabilities are exact rationals.

\begin{definition}[Posterior]
The posterior probability that a fixed player is a werewolf, given only that there
are $k$ werewolves among $n$ players, is
\[
  \post(n,k) = \frac{\binom{n-1}{k-1}}{\binom{n}{k}},
\]
the number of $k$-subsets containing the fixed player divided by the total number of
$k$-subsets.
\end{definition}

\begin{definition}[Prior]
The prior probability that a fixed player is a werewolf is $\prior(n,k)=k/n$.
\end{definition}

\begin{definition}[Werewolf advantage]
The werewolf advantage is $\Adv(n,k)=\dfrac{k}{\,n-k\,}$, defined for $k<n$.
\end{definition}

\begin{definition}[Survival probability]
The probability that a fixed player is not among $t$ uniformly random players
removed from a population of $n$ is
\[
  \surv(n,t)=\frac{\binom{n-1}{t}}{\binom{n}{t}},
\]
the fraction of $t$-subsets avoiding the fixed player.
\end{definition}

\begin{definition}[Consensus-elimination game value]
Let $W(w,v)$ be the villager win-probability of the game with $w$ werewolves and
$v$ villagers alive, in which one uniformly random living player is removed each
round, villagers win when no werewolf remains, and werewolves win upon reaching
parity ($w\ge v$). Then $W(0,v)=1$, $W(w,v)=0$ whenever $w\ge v$ with $w\ge 1$, and
otherwise
\[
  W(w,v)=\frac{w}{w+v}\,W(w-1,v)+\frac{v}{w+v}\,W(w,v-1),
\]
the two branches corresponding to removing a werewolf (probability $w/(w+v)$) or a
villager (probability $v/(w+v)$).
\end{definition}

\section{The Symmetry Principle}

\begin{lemma}[Double-counting identity]\label{lem:dc}
For $1\le k\le n$, \quad $k\,\binom{n}{k}=n\,\binom{n-1}{k-1}.$
\end{lemma}

\begin{proof}[Proof sketch]
Count pairs $(S,x)$ with $S$ a $k$-subset of the $n$ players and $x\in S$
distinguished. Choosing $S$ then $x$ gives $\binom{n}{k}\,k$; choosing $x$ from all
$n$ then the remaining $k-1$ elements from the other $n-1$ gives
$n\,\binom{n-1}{k-1}$. Both count the same pairs.
\end{proof}

\begin{theorem}[Symmetry Principle]\label{thm:sym}
For $1\le k\le n$,
\[
  \post(n,k)=\prior(n,k)=\frac{k}{n}.
\]
With only population counts as evidence, the posterior equals the prior; every
player is equally suspicious and a uniform vote is optimal.
\end{theorem}

\begin{proof}[Proof sketch]
Cross-multiplying, $\binom{n-1}{k-1}/\binom{n}{k}=k/n$ is equivalent to
$n\binom{n-1}{k-1}=k\binom{n}{k}$, which is Lemma~\ref{lem:dc}. The denominators
$\binom{n}{k}$ and $n$ are positive for $1\le k\le n$.
\end{proof}

\begin{corollary}[Baseline detection probability]\label{cor:base}
A single optimal (uniform) vote removes a werewolf with probability exactly $k/n$.
\end{corollary}

Absent behavioral evidence, the town's per-round detection rate is fixed at the raw
prevalence $k/n$, furnishing a clean baseline against which any information-driven
refinement is measured.

\section{Comparative Statics of Suspicion}

\begin{theorem}[Suspicion increases in werewolves]\label{thm:mono-k}
For $n>0$, \quad $\prior(n,k)<\prior(n,k+1)$.
\end{theorem}

\begin{proof}[Proof sketch]
Equal positive denominator $n$; numerators satisfy $k<k+1$.
\end{proof}

\begin{theorem}[Suspicion decreases in population]\label{thm:mono-n}
For $k\ge 1$ and $n\ge 1$, \quad $\prior(n+1,k)<\prior(n,k)$.
\end{theorem}

\begin{proof}[Proof sketch]
The value $k/(n+1)$ versus $k/n$: with $k\ge 1$, the larger denominator yields the
strictly smaller fraction.
\end{proof}

\section{The Werewolf Advantage and the Parity Threshold}

\begin{theorem}[Parity threshold]\label{thm:parity}
For $k<n$, \quad $\Adv(n,k)\ge 1 \iff n\le 2k$.
As long as at least one villager remains, the werewolves are at least as numerous as
the villagers exactly when $n\le 2k$.
\end{theorem}

\begin{proof}[Proof sketch]
Since $k<n$ the denominator $n-k>0$, so $k/(n-k)\ge 1 \iff k\ge n-k \iff 2k\ge n$.
\end{proof}

\begin{theorem}[Advantage increases in werewolves]\label{thm:adv-mono}
For $k+1<n$, \quad $\Adv(n,k)<\Adv(n,k+1)$.
\end{theorem}

\begin{proof}[Proof sketch]
Clearing the positive denominators $n-k$ and $n-k-1$ reduces the claim to
$k(n-k-1)<(k+1)(n-k)$, i.e. $0<n-k$, which holds since $k<n$.
\end{proof}

The parity threshold is an exact algebraic equivalence, not an asymptotic fit. It is
the rigorous replacement for the informal $(1-k/(n-k))^2$ win-probability envelope:
the sharp threshold $n\le 2k$ together with monotonicity of the advantage. Raw count
matters only through distance to parity.

\section{Exchangeability and the Survival Law}

\begin{theorem}[Survival law]\label{thm:surv}
For $t\le n$ and $n\ge 1$, \quad $\surv(n,t)=\dfrac{n-t}{n}$.
A fixed player survives $t$ uniformly random removals with probability exactly
$(n-t)/n$.
\end{theorem}

\begin{proof}[Proof sketch]
Survival means the $t$ removed players form a $t$-subset of the other $n-1$ players:
$\binom{n-1}{t}$ favorable out of $\binom{n}{t}$ total. The companion double-counting
identity $(n-t)\binom{n}{t}=n\binom{n-1}{t}$ collapses the quotient to $(n-t)/n$.
\end{proof}

The survival law turns the multi-night stochastic process into a single fraction,
the surviving proportion of the town.

\section{The Consensus-Elimination Game Is Well Defined}

\begin{theorem}[Value bounds]\label{thm:bounds}
For all configurations $(w,v)$, \quad $0\le W(w,v)\le 1$.
\end{theorem}

\begin{proof}[Proof sketch]
Induct on the number of rounds (a fuel parameter equal to the live population $w+v$
in every reachable call, strictly decreasing along each branch). The base case
$W(0,v)=1$ and the parity case $W=0$ lie in $[0,1]$. Otherwise $W(w,v)$ is a convex
combination $\lambda W(w-1,v)+(1-\lambda)W(w,v-1)$ with $\lambda=w/(w+v)\in[0,1]$; by
induction both summands lie in $[0,1]$, and so does their convex combination.
\end{proof}

The fuel-bounded recursion guarantees termination and rules out a vacuous model, so
all downstream win-probabilities are honest numbers in $[0,1]$.

\section{Algorithms}

\paragraph{Algorithm A (Exact game value by memoized recursion).}
Evaluate $W(w,v)$ by dynamic programming over
$\{(w',v'):w'\le w,\ v'\le v\}$. Each state is a convex combination of two smaller
states, so a bottom-up fill computes all values in $O(w\cdot v)$ exact-rational
operations, seeded by the parity and no-werewolf boundary conditions.

\paragraph{Algorithm B (Baseline vs.\ informed detection).}
Given an evidence model mapping observations to posteriors, compare the informed
single-round detection probability against the baseline $k/n$
(Corollary~\ref{cor:base}). Since the baseline is exact, the value of information is
the well-posed difference of the two, aggregated over rounds via Algorithm A.

\section{Applications}

Werewolf's structure recurs wherever a group identifies a hidden malicious minority
from noisy, strategic, partial information: marketplace fraud detection, compromised
network nodes, insider-threat screening, and moderation against coordinated
manipulation. Three transferable morals follow directly:
\begin{enumerate}[leftmargin=*]
  \item \textbf{Symmetry fixes the baseline.} Without discriminating evidence, the
    detection rate is exactly the prevalence $k/n$ (Corollary~\ref{cor:base}).
  \item \textbf{Ratios, not counts.} Health is governed by $A=k/(n-k)$ with a sharp
    transition at parity (Theorem~\ref{thm:parity}); the order parameter is distance
    to parity $n-2k$.
  \item \textbf{The clock is adversarial.} Because each imperfect round can remove
    the wrong party and value decreases toward parity, time works against the
    defenders.
\end{enumerate}

\section{Discussion and Future Work}

\begin{conjecture}[Parity as a phase transition]
As the werewolf fraction crosses $k=n/2$, the villager win-probability drops
discontinuously to zero and, just below parity, decays like a fixed power of the
villager surplus $n-2k$.
\end{conjecture}

\begin{conjecture}[Bounded value of information]
Any villager strategy using per-round evidence improves single-round detection from
the baseline $k/n$ to at most $1$, and the overall win-probability gain is bounded by
a factor depending only on the number of rounds, not on $n$.
\end{conjecture}

\begin{conjecture}[Square-root werewolf scaling]
For balance---villager win-probability bounded away from $0$ and $1$ as
$n\to\infty$---the number of werewolves must grow on the order of $\sqrt{n}$.
\end{conjecture}

\begin{conjecture}[Monotone comparative statics for mixed rulesets]
The strict monotonicity of suspicion and of the advantage persists verbatim when
nightly eliminations are added, so comparative statics for the consensus model
transfer to full mixed rulesets.
\end{conjecture}

\section{Conclusion}

Beneath the theatrics of accusation and denial, social-deduction games rest on a
compact exact theory: the posterior collapses to the prior $k/n$; suspicion and the
werewolf advantage move monotonically with the population parameters; parity is
reached exactly when $n\le 2k$; a fixed player survives $t$ uniform removals with
probability exactly $(n-t)/n$; and the consensus game has a well-defined value in
$[0,1]$. Together these give a rigorous foundation for optimal Bayesian play and a
template for reasoning about hidden-adversary detection far beyond the game table.

\end{document}

