"""Demo: the Symmetry Principle collapses posterior suspicion to the prior k/n."""
from fractions import Fraction
from math import comb


def posterior(n: int, k: int) -> Fraction:
    """Posterior that a fixed player is a werewolf: C(n-1,k-1)/C(n,k)."""
    return Fraction(comb(n - 1, k - 1), comb(n, k))


def prior(n: int, k: int) -> Fraction:
    """Prior that a fixed player is a werewolf: k/n."""
    return Fraction(k, n)


def demo(max_n: int = 12) -> None:
    ok = True
    for n in range(1, max_n + 1):
        for k in range(1, n + 1):
            if posterior(n, k) != prior(n, k):
                ok = False
                print(f"MISMATCH at n={n}, k={k}")
    print(f"posterior == prior == k/n for all 1<=k<=n<={max_n}: {ok}")
    for n, k in [(7, 2), (10, 3), (15, 4)]:
        print(f"  n={n}, k={k}: posterior = prior = {prior(n, k)} "
              f"(~{float(prior(n, k)):.4f})")


if __name__ == "__main__":
    demo()

"""Demo: exact villager win-probability of the consensus-elimination game."""
from fractions import Fraction
from functools import lru_cache


@lru_cache(maxsize=None)
def win_prob(w: int, v: int) -> Fraction:
    """Exact villager win-probability with w werewolves and v villagers alive.

    Villagers win when w == 0; werewolves win at parity (w >= v). Otherwise one
    uniformly random living player is removed each round.
    """
    if w == 0:
        return Fraction(1)
    if w >= v:
        return Fraction(0)
    total = w + v
    return (Fraction(w, total) * win_prob(w - 1, v)
            + Fraction(v, total) * win_prob(w, v - 1))


def demo() -> None:
    for w, v in [(1, 4), (2, 5), (3, 7), (4, 8), (5, 11)]:
        val = win_prob(w, v)
        assert Fraction(0) <= val <= Fraction(1)
        print(f"  W({w},{v}) = {val} ~ {float(val):.4f}")
    print("all values verified to lie in [0,1]")


if __name__ == "__main__":
    demo()

"""Demo: the survival law surv(n,t) = (n-t)/n under uniform removals."""
from fractions import Fraction
from math import comb


def survival_prob(n: int, t: int) -> Fraction:
    """Probability a fixed player survives t uniform removals: C(n-1,t)/C(n,t)."""
    return Fraction(comb(n - 1, t), comb(n, t))


def demo(max_n: int = 15) -> None:
    ok = all(survival_prob(n, t) == Fraction(n - t, n)
             for n in range(1, max_n + 1) for t in range(0, n + 1))
    print(f"surv(n,t) == (n-t)/n for all t<=n<={max_n}: {ok}")
    for n in [7, 10]:
        row = ", ".join(f"t={t}:{float(survival_prob(n, t)):.3f}"
                        for t in range(0, n + 1))
        print(f"  n={n}: {row}")


if __name__ == "__main__":
    demo()

