from fractions import Fraction
from typing import Dict, Tuple


def win_prob_table(max_w: int, max_v: int) -> Dict[Tuple[int, int], Fraction]:
    """Bottom-up dynamic program for the exact villager win-probability W(w, v).

    Fills all states (w, v) with 0 <= w <= max_w, 0 <= v <= max_v in O(max_w*max_v)
    exact-rational operations. W(0, v) = 1; W(w, v) = 0 at parity (w >= v, w >= 1);
    otherwise W(w, v) is the convex combination of the two child states.
    """
    W: Dict[Tuple[int, int], Fraction] = {}
    for w in range(0, max_w + 1):
        for v in range(0, max_v + 1):
            if w == 0:
                W[(w, v)] = Fraction(1)
            elif w >= v:
                W[(w, v)] = Fraction(0)
            else:
                total = w + v
                W[(w, v)] = (Fraction(w, total) * W[(w - 1, v)]
                             + Fraction(v, total) * W[(w, v - 1)])
    return W

