"""Visualization: heatmap of the exact villager win-probability W(w, v)."""
from fractions import Fraction
from functools import lru_cache

import matplotlib.pyplot as plt
import numpy as np


@lru_cache(maxsize=None)
def win_prob(w: int, v: int) -> Fraction:
    if w == 0:
        return Fraction(1)
    if w >= v:
        return Fraction(0)
    total = w + v
    return (Fraction(w, total) * win_prob(w - 1, v)
            + Fraction(v, total) * win_prob(w, v - 1))


def main() -> None:
    W, V = 10, 16
    grid = np.zeros((W + 1, V + 1))
    for w in range(W + 1):
        for v in range(V + 1):
            grid[w, v] = float(win_prob(w, v))
    plt.figure(figsize=(8, 5))
    plt.imshow(grid, origin="lower", aspect="auto", cmap="viridis")
    plt.colorbar(label="villager win probability W(w, v)")
    plt.xlabel("villagers v")
    plt.ylabel("werewolves w")
    plt.title("Consensus-elimination game value")
    plt.tight_layout()
    plt.savefig("winprob_heatmap.png", dpi=150)
    print("saved winprob_heatmap.png")


if __name__ == "__main__":
    main()
